mapper.select:
SELECT A.ATTEND_ID, A.EMPNO, E.ENAME, D.DNAME, TO_CHAR(A.WORK_DATE, 'YYYY-MM-DD') AS WORK_DATE, TO_CHAR(A.CHECK_IN, 'HH24:MI') AS CHECK_IN, TO_CHAR(A.CHECK_OUT, 'HH24:MI') AS CHECK_OUT, A.WORK_MINUTES, A.STATUS, A.NOTE, TO_CHAR(A.CREATED_AT, 'YYYY-MM-DD HH24:MI:SS') AS CREATED_AT FROM ATTENDANCE A JOIN EMP E ON A.EMPNO = E.EMPNO JOIN DEPT D ON E.DEPTNO = D.DEPTNO
AND TO_CHAR(A.WORK_DATE, 'YYYY-MM-DD') = #{date}
AND E.DEPTNO = #{deptno}
ORDER BY A.WORK_DATE DESC, E.ENAME
